d":"pdf-g12","pillar":"work","t":"Casa de Veux: 5 connections a week, 10 in-person meetings a market week, 4 brand pitches a month, 3 season retainers by Q2 2027","p":0,"why":""},{"id":"pdf-g13","pillar":"work","t":"CAVYRE: 3 founding agencies paying by Jan 3, all 5 paying by Mar 31, 12 agencies by Jun 30, 2027","p":0,"why":""}],"tasks":[{"id":"pdf-t1","title":"Book the December New York and Paris trip","due":"2026-11-10","pillar":"daily","done":false,"note":"Atlanta to New York, Nov 30; New York to Paris overnight, Dec 6; Paris to Atlanta, Dec 13; New York hotel, Nov 30 to Dec 6; Paris hotel, Dec 7 to 13"},{"id":"pdf-t2","title":"US work visas for NYFW","due":"2026-11-13","pillar":"work","done":false,"note":"Aidan Jake; Violeta Rodo; Zhiyan Li; Clara Wahlqvist: status from her lawyer"},{"id":"pdf-t3","title":"MDV: first 4 new signings","due":"2026-11-15","pillar":"work","done":false,"note":"Shortlist 10 prospects; digitals for the top 5; test shoots via CDV; 4 contracts signed"},{"id":"pdf-t4","title":"CAVYRE: first founding agency signed","due":"2026-11-20","pillar":"work","done":false,"note":"Demo script on the live MDV desk; pricing one-pager; 10 walkthroughs done; follow-ups within 24 hours; first founding agreement signed"},{"id":"pdf-t5","title":"MDV: NY open call (Dec 1 to 5 week)","due":"2026-11-25","pillar":"work","done":false,"note":"Pick the venue and date; application form live; announce on Instagram; staff the day with Emma's team"},{"id":"pdf-t6","title":"CDV: 4 new brand pitches (November)","due":"2026-11-30","pillar":"work","done":false,"note":"Brand 1; Brand 2; Brand 3; Brand 4"},{"id":"pdf-t7","title":"Find a business mentor","due":"2026-11-30","pillar":"personal","done":false,"note":"List 5 candidates; reach out to 3; first meeting booked"},{"id":"pdf-t8","title":"MDV: Paris open call (Dec 7 to 12 week)","due":"2026-12-01","pillar":"work","done":false,"note":"Pick the venue and date; application form live; announce on Instagram; staff the day with Erica's team"},{"id":"pdf-t9","title":"Hire a Paris booker or assistant","due":"2026-12-12","pillar":"work","done":false,"note":"Write the role; post it; shortlist 5; interviews during the Nov 9 to 14 Paris week; second round in December; offer made"},{"id":"pdf-t10","title":"Eye exam","due":"2026-12-15","pillar":"life","done":false,"note":"Book; attend"},{"id":"pdf-t11","title":"MDV: NY studio decision","due":"2026-12-18","pillar":"work","done":false,"note":"Shortlist Garment District and West Chelsea spaces; tours during the Nov 3 to 6 NY week; budget review with Sophia; decision made"},{"id":"pdf-t12","title":"CDV: SS27 retainer proposals","due":"2026-12-18","pillar":"work","done":false,"note":"Pick 3 target clients; retainer scope and pricing; proposals sent; follow-ups booked"},{"id":"pdf-t13","title":"Complete the capsule wardrobe","due":"2026-12-18","pillar":"personal","done":false,"note":"Shoes; watch; leather bag; knits and tees"},{"id":"pdf-t14","title":"MDV: 12 new signings toward the boards (20, 20 and 20 per city)","due":"2027-01-03","pillar":"work","done":false,"note":"4 by Nov 15; 8 by Dec 6; 12 by Jan 3"},{"id":"pdf-t15","title":"CAVYRE: 5 founding agencies live, 3 paying","due":"2027-01-03","pillar":"work","done":false,"note":"Agency 1; Agency 2; Agency 3; Agency 4; Agency 5"}],"events":[{"id":"pdf-e1","d":"2026-11-02","t":"","title":"Fly Atlanta to New York with Emma · CFDA Awards night","cat":"work","note":""},{"id":"pdf-e2","d":"2026-11-08","t":"","title":"Fly New York to Paris (overnight)","cat":"daily","note":""},{"id":"pdf-e3","d":"2026-11-11","t":"","title":"Paris Photo vernissage","cat":"work","note":""},{"id":"pdf-e4","d":"2026-11-12","t":"","title":"Haircut (Paris barber)","cat":"personal","note":""},{"id":"pdf-e5","d":"2026-11-15","t":"","title":"Fly Paris to Atlanta · CAVYRE: 10 walkthroughs done","cat":"work","note":""},{"id":"pdf-e6","d":"2026-11-20","t":"","title":"Finance review with Sophia","cat":"work","note":""},{"id":"pdf-e7","d":"2026-11-25","t":"","title":"Haircut","cat":"personal","note":""},{"id":"pdf-e8","d":"2026-11-26","t":"","title":"Thanksgiving with family","cat":"personal","note":""},{"id":"pdf-e9","d":"2026-11-29","t":"","title":"Monthly review","cat":"work","note":""},{"id":"pdf-e10","d":"2026-11-30","t":"","title":"Fly Atlanta to New York","cat":"daily","note":""},{"id":"pdf-e11","d":"2026-12-06","t":"","title":"Fly New York to Paris (overnight)","cat":"daily","note":""},{"id":"pdf-e12","d":"2026-12-10","t":"","title":"Haircut (Paris barber)","cat":"personal","note":""},{"id":"pdf-e13","d":"2026-12-13","t":"","title":"Fly Paris to Atlanta · CAVYRE: 5 founding agencies onboarded","cat":"work","note":""},{"id":"pdf-e14","d":"2026-12-18","t":"","title":"Finance review with Sophia","cat":"work","note":""},{"id":"pdf-e15","d":"2026-12-23","t":"","title":"Haircut","cat":"personal","note":""},{"id":"pdf-e16","d":"2026-12-27","t":"","title":"Monthly review","cat":"work","note":""},{"id":"pdf-e17","d":"2027-01-02","t":"","title":"90-day review","cat":"work","note":""},{"id":"pdf-e18","d":"2027-01-15","t":"","title":"Milan Men's FW27 begins (models arrive Jan 8)","cat":"work","note":""},{"id":"pdf-e19","d":"2027-01-19","t":"","title":"Paris Men's FW27 begins (models arrive Jan 10)","cat":"work","note":""},{"id":"pdf-e20","d":"2027-01-25","t":"","title":"Paris Haute Couture SS27 begins (models arrive Jan 15)","cat":"work","note":""},{"id":"pdf-e21","d":"2027-02-11","t":"","title":"New York Fashion Week FW27 begins (models arrive Jan 30)","cat":"work","note":""}],"days":[{"doc_id":"d2026-11-02","data":{"tmpl":"pdf-travel"}},{"doc_id":"d2026-11-03","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-11-04","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-11-05","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-11-06","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-11-07","data":{"tmpl":"pdf-mktwknd"}},{"doc_id":"d2026-11-08","data":{"tmpl":"pdf-travel"}},{"doc_id":"d2026-11-09","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-11-10","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-11-11","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-11-12","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-11-13","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-11-14","data":{"tmpl":"pdf-mktwknd"}},{"doc_id":"d2026-11-15","data":{"tmpl":"pdf-travel"}},{"doc_id":"d2026-11-30","data":{"tmpl":"pdf-travel"}},{"doc_id":"d2026-12-01","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-12-02","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-12-03","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-12-04","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-12-05","data":{"tmpl":"pdf-mktwknd"}},{"doc_id":"d2026-12-06","data":{"tmpl":"pdf-travel"}},{"doc_id":"d2026-12-07","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-12-08","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-12-09","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-12-10","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-12-11","data":{"tmpl":"pdf-market"}},{"doc_id":"d2026-12-12","data":{"tmpl":"pdf-mktwknd"}},{"doc_id":"d2026-12-13","data":{"tmpl":"pdf-travel"}}]}$json$::jsonb;
begin
  select id into uid from auth.users where lower(email) = 'demontez@maisondeveux.com';
  if uid is null then raise exception 'No portal login found for demontez@maisondeveux.com'; end if;
  select data into c from public.daysilk_docs where user_id = uid and doc_id = 'core';
  if c is null then raise exception 'Open the DaySilk page in the portal once, then run this again'; end if;

  -- templates: drop the ones being replaced, add the new set
  c := jsonb_set(c, '{templates}',
    coalesce((select jsonb_object_agg(e.k, e.v) from jsonb_each(coalesce(c->'templates','{}'::jsonb)) as e(k,v)
              where not exists (select 1 from jsonb_each(p->'templates') as y(kk,x) where lower(x->>'n') = lower(e.v->>'n'))
                and lower(coalesce(e.v->>'n','')) <> 'new york market day'), '{}'::jsonb)
    || (p->'templates'), true);

  c := jsonb_set(c, '{week}',  coalesce(c->'week','{}'::jsonb)  || (p->'week'),  true);
  c := jsonb_set(c, '{train}', coalesce(c->'train','{}'::jsonb) || (p->'train'), true);
  c := jsonb_set(c, '{day}',   coalesce(c->'day','{}'::jsonb)   || (p->'day'),   true);

  -- profile: fill in blanks, keep anything already filled in
  prof := coalesce((select jsonb_object_agg(e.k, e.v) from jsonb_each(coalesce(c->'profile','{}'::jsonb)) as e(k,v)
                    where e.v <> '""'::jsonb and e.v <> 'null'::jsonb), '{}'::jsonb);
  c := jsonb_set(c, '{profile}', (p->'profile') || prof, true);

  -- habits, goals, tasks, events: add only what is not already there
  c := jsonb_set(c, '{habits}', coalesce(c->'habits','[]'::jsonb) ||
    coalesce((select jsonb_agg(h) from jsonb_array_elements(p->'habits') as h
              where not exists (select 1 from jsonb_array_elements(coalesce(c->'habits','[]'::jsonb)) as x where lower(x#>>'{}') = lower(h#>>'{}'))), '[]'::jsonb), true);
  c := jsonb_set(c, '{goals}', coalesce(c->'goals','[]'::jsonb) ||
    coalesce((select jsonb_agg(h) from jsonb_array_elements(p->'goals') as h
              where not exists (select 1 from jsonb_array_elements(coalesce(c->'goals','[]'::jsonb)) as x where lower(x->>'t') = lower(h->>'t'))), '[]'::jsonb), true);
  c := jsonb_set(c, '{tasks}', coalesce(c->'tasks','[]'::jsonb) ||
    coalesce((select jsonb_agg(h) from jsonb_array_elements(p->'tasks') as h
              where not exists (select 1 from jsonb_array_elements(coalesce(c->'tasks','[]'::jsonb)) as x where lower(x->>'title') = lower(h->>'title'))), '[]'::jsonb), true);
  c := jsonb_set(c, '{events}', coalesce(c->'events','[]'::jsonb) ||
    coalesce((select jsonb_agg(h) from jsonb_array_elements(p->'events') as h
              where not exists (select 1 from jsonb_array_elements(coalesce(c->'events','[]'::jsonb)) as x where x->>'d' = h->>'d' and lower(x->>'title') = lower(h->>'title'))), '[]'::jsonb), true);

  update public.daysilk_docs set data = c where user_id = uid and doc_id = 'core';

  -- which template each day of the NY / Paris trips uses
  insert into public.daysilk_docs (user_id, doc_id, data)
  select uid, dd->>'doc_id', dd->'data' from jsonb_array_elements(p->'days') as dd
  on conflict (user_id, doc_id) do update set data = public.daysilk_docs.data || excluded.data;
end $$;

-- Check: should show 10 or more templates, plenty of tasks and events.
select (select count(*) from jsonb_object_keys(data->'templates')) as templates,
       jsonb_array_length(data->'habits') as habits,
       jsonb_array_length(data->'goals') as goals,
       jsonb_array_length(data->'tasks') as tasks,
       jsonb_array_length(data->'events') as events
from public.daysilk_docs
where doc_id = 'core' and user_id = (select id from auth.users where lower(email) = 'demontez@maisondeveux.com');
